mapper.select:
SELECT rr.id, rr.no, rr.user_id AS userId, u.nickname AS userName, rr.coupon_id AS couponId, cm.name AS couponName, rr.receive_time AS receiveTime, rr.status, rr.verify_time AS verifyTime, rr.check_result AS checkResult, rr.sync_status AS syncStatus, rr.archive_time AS archiveTime, rr.creator, rr.create_time AS createTime, rr.update_time AS updateTime FROM receive_record rr LEFT JOIN user_info u ON rr.user_id = u.id AND u.deleted = 0 LEFT JOIN coupon_mgmt cm ON rr.coupon_id = cm.id AND cm.deleted = 0 WHERE rr.deleted = 0
AND rr.user_id = #{reqVO.userId}
AND rr.coupon_id = #{reqVO.couponId}
AND rr.status = #{reqVO.status}
AND rr.sync_status = #{reqVO.syncStatus}
AND rr.receive_time BETWEEN #{reqVO.receiveTime[0]} AND #{reqVO.receiveTime[1]}
AND rr.receive_time BETWEEN DATE(#{reqVO.date}) AND DATE(DATE_ADD(#{reqVO.date}, INTERVAL 1 DAY))
AND rr.create_time BETWEEN DATE(FROM_UNIXTIME(#{reqVO.startTime} / 1000)) AND DATE(FROM_UNIXTIME(#{reqVO.endTime} / 1000))
AND rr.create_time >= DATE(FROM_UNIXTIME(#{reqVO.startTime} / 1000))
AND rr.create_time <= DATE(FROM_UNIXTIME(#{reqVO.endTime} / 1000))
ORDER BY rr.id DESC
